package android.net.nsd;import java.net.*;import java.util.*;public class NsdServiceInfo {public android.net.Network network;public android.net.Network getNetwork(){return network;}public String name,type;public int port;public InetAddress host;public List<InetAddress> addresses=new ArrayList<>();public String getServiceName(){return name;}public String getServiceType(){return type;}public int getPort(){return port;}public InetAddress getHost(){return host;}public List<InetAddress> getHostAddresses(){return addresses;}}
